declare(strict_types=1);spl_autoload_register(static function(string$c):void{$p='ImAuthenticator\\';if(!str_starts_with($c,$p))return;$f=dirname(__DIR__).'/src/'.str_replace('\\','/',substr($c,strlen($p))).'.php';if(is_file($f))require$f;});use ImAuthenticator\AuditLog;use ImAuthenticator\Database;function okImmutable(bool$c,string$m):void{if(!$c){fwrite(STDERR,"FAIL: {$m}\n");exit(1);}fwrite(STDOUT,"OK: {$m}\n");}$env=static fn(string$n,string$d)=>(getenv($n)===false?$d:(string)getenv($n));$db=new Database(['dsn'=>$env('TEST_DB_DSN','mysql:host=127.0.0.1;dbname=imauth_ci;charset=utf8mb4'),'user'=>$env('TEST_DB_USER','root'),'pass'=>$env('TEST_DB_PASS','')]);$audit=new AuditLog($db);$audit->write('test.audit.immutable','success');$row=$db->one("SELECT id FROM audit_log WHERE action='test.audit.immutable' ORDER BY id DESC LIMIT 1");$id=(int)$row['id'];$blockedUpdate=false;try{$db->execute("UPDATE audit_log SET reason='tampered' WHERE id=?",[$id]);}catch(Throwable){$blockedUpdate=true;}okImmutable($blockedUpdate,'audit UPDATE is rejected by MySQL trigger');$blockedDelete=false;try{$db->execute('DELETE FROM audit_log WHERE id=?',[$id]);}catch(Throwable){$blockedDelete=true;}okImmutable($blockedDelete,'ordinary audit DELETE is rejected');$db->execute('SET @imauth_allow_audit_delete=1');try{$deleted=$db->execute('DELETE FROM audit_log WHERE id=?',[$id]);}finally{$db->execute('SET @imauth_allow_audit_delete=0');}okImmutable($deleted===1,'retention session can delete audit row explicitly');fwrite(STDOUT,"Audit immutability smoke test passed.\n");
